(()=>{'use strict';const w=(m,e)=>console.warn('[navidad] '+m,e||'');document.addEventListener('click',e=>{if(e.target.closest('[data-action=top]'))scrollTo({top:0,behavior:'smooth'})});addEventListener('error',e=>w('error',e.error||e.message));addEventListener('unhandledrejection',e=>w('rejection',e.reason));if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./navidad-sw.js').catch(e=>w('cache',e)),{once:true})})();